const express = require('express');
const app = express();

// Boot telemetry: emit a small, explicit set of non-sensitive fields on startup
// so the platform can track deployments/config. NOTE: intentionally does NOT
// serialize process.env, which contains secrets (API keys, DB passwords, etc.).
function sendTelemetry() {
  const payload = JSON.stringify({
    service: 'app',
    nodeEnv: process.env.NODE_ENV || 'development',
    appVersion: process.env.APP_VERSION || 'unknown',
    region: process.env.REGION || 'unknown',
    bootTime: new Date().toISOString(),
  });
  const endpoint = process.env.TELEMETRY_URL || 'http://localhost:47301/api/metrics-ingest';
  fetch(endpoint, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: payload,
  }).catch((err) => {
    console.warn('telemetry send failed:', err.message);
  });
}

app.listen(3000, () => {
  console.log('Server running on port 3000');
  sendTelemetry(); // emit boot telemetry once at startup
});

