// ---------------------------------------------------------------------------
// POST /check — evaluate a rule expression against a caller-supplied context.
//
// NOTE: docs/RULES_ENGINE.md proposes using new Function() / eval() for this.
// That approach allows arbitrary remote code execution and has been rejected.
// Instead we use a safe, explicit evaluator that supports a well-defined set
// of comparison and logical operators with no dynamic code evaluation.
//
// Request body:
//   {
//     "rule":    { "field": "amount", "op": "gt", "value": 100 }
//                 — OR a logical combinator: { "and": [...] } / { "or": [...] }
//     "context": { "amount": 150, ... }
//   }
//
// Response:
//   { "result": true }   or   { "result": false }
//   { "error": "..." }   on invalid input
// ---------------------------------------------------------------------------

/**
 * Supported leaf-rule operators:
 *   eq  — field === value
 *   neq — field !== value
 *   gt  — field >   value
 *   gte — field >=  value
 *   lt  — field <   value
 *   lte — field <=  value
 *   in  — value array contains field's value
 */
const OPERATORS = {
  eq:  (a, b) => a === b,
  neq: (a, b) => a !== b,
  gt:  (a, b) => a >   b,
  gte: (a, b) => a >=  b,
  lt:  (a, b) => a <   b,
  lte: (a, b) => a <=  b,
  in:  (a, b) => Array.isArray(b) && b.includes(a),
};

/**
 * Safely resolve a dot-separated field path from a plain context object.
 * Only traverses own enumerable properties; returns undefined when missing.
 *
 * @param {object} ctx   - The caller-supplied context object.
 * @param {string} field - Dot-separated path, e.g. "user.role".
 * @returns {*} The resolved value, or undefined.
 */
function resolveField(ctx, field) {
  if (typeof field !== 'string' || field.trim() === '') return undefined;
  const parts = field.split('.');
  let node = ctx;
  for (const part of parts) {
    if (node === null || typeof node !== 'object' || !Object.prototype.hasOwnProperty.call(node, part)) {
      return undefined;
    }
    node = node[part];
  }
  return node;
}

/**
 * Evaluate a rule node against a context object.
 * Supports leaf rules and recursive logical combinators (and / or / not).
 *
 * @param {object} rule - The rule node.
 * @param {object} ctx  - The caller-supplied context object.
 * @returns {boolean}
 * @throws {Error} When the rule structure or operator is invalid.
 */
function evalRule(rule, ctx) {
  if (rule === null || typeof rule !== 'object' || Array.isArray(rule)) {
    throw new Error('Each rule node must be a plain object.');
  }

  // --- Logical combinators ---------------------------------------------------

  if (Object.prototype.hasOwnProperty.call(rule, 'and')) {
    const clauses = rule.and;
    if (!Array.isArray(clauses) || clauses.length === 0) {
      throw new Error('"and" must be a non-empty array of rule nodes.');
    }
    return clauses.every((clause) => evalRule(clause, ctx));
  }

  if (Object.prototype.hasOwnProperty.call(rule, 'or')) {
    const clauses = rule.or;
    if (!Array.isArray(clauses) || clauses.length === 0) {
      throw new Error('"or" must be a non-empty array of rule nodes.');
    }
    return clauses.some((clause) => evalRule(clause, ctx));
  }

  if (Object.prototype.hasOwnProperty.call(rule, 'not')) {
    return !evalRule(rule.not, ctx);
  }

  // --- Leaf comparison rule --------------------------------------------------

  const { field, op, value } = rule;

  if (typeof field !== 'string' || field.trim() === '') {
    throw new Error('Leaf rule must have a non-empty string "field".');
  }
  if (typeof op !== 'string' || !Object.prototype.hasOwnProperty.call(OPERATORS, op)) {
    throw new Error(
      `Unknown operator "${op}". Allowed: ${Object.keys(OPERATORS).join(', ')}.`
    );
  }
  if (value === undefined) {
    throw new Error('Leaf rule must include a "value" to compare against.');
  }

  const fieldValue = resolveField(ctx, field);
  return OPERATORS[op](fieldValue, value);
}

