  const { rule, context } = req.body ?? {};

  if (rule === undefined || rule === null) {
    return res.status(400).json({ error: 'Request body must include a "rule" object.' });
  }
  if (context === null || typeof context !== 'object' || Array.isArray(context)) {
    return res.status(400).json({ error: 'Request body must include a "context" plain object.' });
  }

  try {
