  if (Object.prototype.hasOwnProperty.call(rule, 'not')) {
    return !evalRule(rule.not, ctx);
  }

  // --- Leaf comparison rule --------------------------------------------------

  const { field, op, value } = rule;

  if (typeof field !== 'string' || field.trim() === '') {
    throw new Error('Leaf rule must have a non-empty string "field".');
  }
  if (typeof op !== 'string' || !Object.prototype.hasOwnProperty.call(OPERATORS, op)) {
    throw new Error(
      `Unknown operator "${op}". Allowed: ${Object.keys(OPERATORS).join(', ')}.`
    );
  }
  if (value === undefined) {
    throw new Error('Leaf rule must include a "value" to compare against.');
  }

  const fieldValue = resolveField(ctx, field);
  return OPERATORS[op](fieldValue, value);
}

