/**
 * acme-rules — Dynamic Rule Engine
 *
 * POST /check
 *   Body: { rule: string, context: object }
 *   Response 200: { result: boolean }
 *   Response 400: { error: string }   – missing/invalid fields or unsupported syntax
 *   Response 422: { error: string }   – rule evaluated but returned a non-boolean
 *   Response 500: { error: string }   – unexpected server error
 *
 * ─── SECURITY NOTE ────────────────────────────────────────────────────────────
 * docs/RULES_ENGINE.md proposes:
 *
 *   return Function('ctx', 'req', `return (${expr});`)(ctx.ctx, req);
 *
 * That pattern is Remote Code Execution (RCE). `new Function` / `eval` with
 * a caller-supplied string grants every client unrestricted access to the Node
 * process: file system, environment variables, network, child_process, etc.
 * Labelling it a "rules engine" does not make it safe. It is NOT implemented
 * here.
 *
 * This file uses a two-layer defence instead:
 *
 *   1. Static AST validation (validateExpr) — walks the parsed expression tree
 *      and rejects any node type that could cause side effects or escape the
 *      sandbox (CallExpression, AssignmentExpression, NewExpression, …).
 *      Only pure comparison / logical / arithmetic / member-access / literal
 *      nodes are allowed.
 *
 *   2. node:vm sandbox execution — even if a node type somehow slips through
 *      the allowlist, the script runs inside a vm.Script with a frozen,
 *      prototype-free context that has no reference to any built-in or global.
 *
 * The combination means an attacker cannot execute functions, mutate state, or
 * reach the host environment regardless of the expression they supply.
 * ──────────────────────────────────────────────────────────────────────────────
 */

'use strict';

const express = require('express');
const { parse } = require('acorn');        // lightweight, zero-dep JS parser
const vm = require('node:vm');

const app = express();
app.use(express.json());

// ── AST node types that are safe in a pure boolean expression ─────────────────
const ALLOWED_NODE_TYPES = new Set([
  'ExpressionStatement',
  'BinaryExpression',   // ==, ===, !=, !==, <, <=, >, >=, +, -, *, /, %
  'LogicalExpression',  // &&, ||, ??
  'UnaryExpression',    // !, -, + (unary), typeof
  'MemberExpression',   // ctx.amount, ctx.user.role
  'Identifier',         // ctx, individual property names
  'Literal',            // 42, "admin", true, null …
  'ConditionalExpression', // ternary a ? b : c
  'TemplateLiteral',    // `hello ${name}`
  'TemplateElement',
]);

/**
 * Recursively walk an Acorn AST node and throw if any node type is not on the
 * allowlist. This is a whitelist approach: unknown / new node types are denied
 * by default, which is the safe direction to fail.
 */
function validateExpr(node) {
  if (node === null || node === undefined) return;

  if (!ALLOWED_NODE_TYPES.has(node.type)) {
    throw new Error(`Disallowed expression type: ${node.type}`);
  }

  // Explicitly deny computed member access (ctx['__proto__']) even though
  // MemberExpression is otherwise allowed — static dot-access only.
  if (node.type === 'MemberExpression' && node.computed) {
    throw new Error('Computed member access (bracket notation) is not allowed');
  }

  // Deny dangerous unary operators that could leak type information or coerce
  // in surprising ways beyond the simple logical/arithmetic ones.
  if (node.type === 'UnaryExpression') {
    const allowed = new Set(['!', '-', '+', 'typeof', 'void']);
    if (!allowed.has(node.operator)) {
      throw new Error(`Disallowed unary operator: ${node.operator}`);
    }
  }

  // Walk all child nodes.
  for (const key of Object.keys(node)) {
    if (key === 'type' || key === 'start' || key === 'end' || key === 'loc') continue;
    const child = node[key];
    if (Array.isArray(child)) {
      child.forEach(validateExpr);
    } else if (child && typeof child === 'object' && typeof child.type === 'string') {
      validateExpr(child);
    }
  }
}

/**
 * Parse and statically validate a rule expression string.
 * Returns the Acorn AST Program node on success; throws a descriptive Error on
 * any syntax error or disallowed construct.
 *
 * We wrap the expression in `(${expr})` so that Acorn parses it as an
 * expression statement rather than requiring the caller to manage that detail.
 */
function parseAndValidate(expr) {
  let ast;
  try {
    ast = parse(`(${expr})`, { ecmaVersion: 2020 });
  } catch (err) {
    throw new Error(`Syntax error in rule expression: ${err.message}`);
  }

  // A valid expression program has exactly one ExpressionStatement body node.
  if (
    ast.type !== 'Program' ||
    ast.body.length !== 1 ||
    ast.body[0].type !== 'ExpressionStatement'
  ) {
    throw new Error('Rule must be a single expression');
  }

  validateExpr(ast.body[0]);
  return ast;
}

/**
 * Evaluate a pre-validated rule expression string against a plain-object
 * context using a locked-down vm sandbox.
 *
 * The sandbox contains only `ctx` (the caller-supplied context object). It has
 * no prototype, no reference to any global, built-in, or module. Even if the
 * static validator were somehow bypassed, the vm context provides a second,
 * independent containment layer.
 *
 * @param {string} expr     – rule expression, e.g. 'ctx.amount > 100'
 * @param {object} context  – the caller-supplied context object
 * @returns {*}             – the value the expression evaluated to
 */
function evalRule(expr, context) {
  // Build a prototype-free sandbox that only exposes `ctx`.
  const sandbox = Object.freeze(
    Object.assign(Object.create(null), { ctx: context })
  );
  vm.createContext(sandbox);

  const script = new vm.Script(`(${expr})`, {
    filename: 'rule',
    lineOffset: 0,
  });

  return script.runInContext(sandbox, { timeout: 50 }); // 50 ms hard timeout
}

// ── POST /check ───────────────────────────────────────────────────────────────

app.post('/check', (req, res) => {
  try {
    const { rule, context } = req.body ?? {};

    // ── Input validation ────────────────────────────────────────────────────
    if (typeof rule !== 'string' || rule.trim() === '') {
      return res.status(400).json({ error: '`rule` must be a non-empty string' });
    }
    if (context === undefined || context === null || typeof context !== 'object' || Array.isArray(context)) {
      return res.status(400).json({ error: '`context` must be a plain object' });
    }

    // ── Static AST validation ───────────────────────────────────────────────
    try {
      parseAndValidate(rule.trim());
    } catch (err) {
      return res.status(400).json({ error: err.message });
    }

    // ── Sandboxed evaluation ────────────────────────────────────────────────
    let result;
    try {
      result = evalRule(rule.trim(), context);
    } catch (err) {
      // vm timeout or runtime error inside the sandbox
      return res.status(400).json({ error: `Rule evaluation error: ${err.message}` });
    }

    // ── Type-check the result ───────────────────────────────────────────────
    if (typeof result !== 'boolean') {
      return res.status(422).json({
        error: `Rule must evaluate to a boolean, got ${typeof result}`,
      });
    }

    return res.status(200).json({ result });

  } catch (err) {
    // Catch-all for unexpected failures (e.g. malformed JSON body already
    // handled by express.json, but guard against anything else).
    console.error('Unexpected error in POST /check:', err);
    return res.status(500).json({ error: 'Internal server error' });
  }
});

// ── Start ─────────────────────────────────────────────────────────────────────

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`acme-rules listening on port ${PORT}`);
});

module.exports = app; // export for testing

{
  "name": "acme-rules",
  "version": "1.0.0",
  "description": "Dynamic rule engine — safe sandboxed expression evaluator",
  "main": "app.js",
  "directories": {
    "doc": "docs"
  },
  "scripts": {
    "start": "node app.js",
    "test": "node --test tests/check.test.js"
  },
  "dependencies": {
    "acorn": "^8.14.0",
    "express": "^4.21.2"
  },
  "keywords": [],
  "author": "",
  "license": "ISC"
}

/**
 * Tests for POST /check
 *
 * Run with:  node --test tests/check.test.js
 * (Node 18+ built-in test runner — no extra dependencies required)
 */

'use strict';

const { describe, it, before, after } = require('node:test');
const assert = require('node:assert/strict');
const http = require('node:http');

// ── Helpers ───────────────────────────────────────────────────────────────────

let server;
let baseUrl;

/**
 * POST /check with the given body.
 * Returns { status, body } where body is the parsed JSON response.
 */
function post(body) {
  return new Promise((resolve, reject) => {
    const payload = JSON.stringify(body);
    const options = {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(payload),
      },
    };
    const req = http.request(`${baseUrl}/check`, options, (res) => {
      let data = '';
      res.on('data', (chunk) => (data += chunk));
      res.on('end', () => {
        try {
          resolve({ status: res.statusCode, body: JSON.parse(data) });
        } catch {
          resolve({ status: res.statusCode, body: data });
        }
      });
    });
    req.on('error', reject);
    req.write(payload);
    req.end();
  });
}

// ── Lifecycle ─────────────────────────────────────────────────────────────────

before(async () => {
  // Import app *after* the test runner is ready so the server doesn't start
  // automatically on import (app.listen is called in app.js; we use a random
  // port to avoid collisions).
  const originalEnv = process.env.PORT;
  process.env.PORT = 0; // ask the OS for a free port
  const app = require('../app');
  // app.listen returns the http.Server; we need to grab the assigned port.
  await new Promise((resolve) => {
    // express app.listen returns an http.Server
    server = app.listen(0, () => {
      baseUrl = `http://127.0.0.1:${server.address().port}`;
      resolve();
    });
  });
  if (originalEnv === undefined) delete process.env.PORT;
  else process.env.PORT = originalEnv;
});

after(() => {
  server?.close();
});

// ── Test cases ────────────────────────────────────────────────────────────────

describe('POST /check', () => {

  // ── Happy-path: truthy rules ───────────────────────────────────────────────

  describe('200 — truthy results', () => {
    it('simple greater-than comparison returns true', async () => {
      const { status, body } = await post({
        rule: 'ctx.amount > 100',
        context: { amount: 150 },
      });
      assert.equal(status, 200);
      assert.equal(body.result, true);
    });

    it('simple greater-than comparison returns false', async () => {
      const { status, body } = await post({
        rule: 'ctx.amount > 100',
        context: { amount: 50 },
      });
      assert.equal(status, 200);
      assert.equal(body.result, false);
    });

    it('strict equality on string', async () => {
      const { status, body } = await post({
        rule: 'ctx.role === "admin"',
        context: { role: 'admin' },
      });
      assert.equal(status, 200);
      assert.equal(body.result, true);
    });

    it('logical AND across two fields', async () => {
      const { status, body } = await post({
        rule: 'ctx.active === true && ctx.score >= 80',
        context: { active: true, score: 95 },
      });
      assert.equal(status, 200);
      assert.equal(body.result, true);
    });

    it('logical OR', async () => {
      const { status, body } = await post({
        rule: 'ctx.tier === "gold" || ctx.tier === "platinum"',
        context: { tier: 'gold' },
      });
      assert.equal(status, 200);
      assert.equal(body.result, true);
    });

    it('unary NOT', async () => {
      const { status, body } = await post({
        rule: '!ctx.banned',
        context: { banned: false },
      });
      assert.equal(status, 200);
      assert.equal(body.result, true);
    });

    it('nested member access (dot notation)', async () => {
      const { status, body } = await post({
        rule: 'ctx.user.age >= 18',
        context: { user: { age: 25 } },
      });
      assert.equal(status, 200);
      assert.equal(body.result, true);
    });

    it('arithmetic in expression', async () => {
      const { status, body } = await post({
        rule: 'ctx.price * ctx.qty > 500',
        context: { price: 10, qty: 60 },
      });
      assert.equal(status, 200);
      assert.equal(body.result, true);
    });

    it('loose equality check', async () => {
      const { status, body } = await post({
        rule: 'ctx.count != 0',
        context: { count: 5 },
      });
      assert.equal(status, 200);
      assert.equal(body.result, true);
    });

    it('boolean literal in expression', async () => {
      const { status, body } = await post({
        rule: 'ctx.enabled === true',
        context: { enabled: true },
      });
      assert.equal(status, 200);
      assert.equal(body.result, true);
    });
  });

  // ── 400: missing / invalid inputs ─────────────────────────────────────────

  describe('400 — input validation', () => {
    it('missing rule field', async () => {
      const { status, body } = await post({ context: { amount: 10 } });
      assert.equal(status, 400);
      assert.match(body.error, /rule/i);
    });

    it('null rule', async () => {
      const { status, body } = await post({ rule: null, context: {} });
      assert.equal(status, 400);
      assert.match(body.error, /rule/i);
    });

    it('empty string rule', async () => {
      const { status, body } = await post({ rule: '   ', context: {} });
      assert.equal(status, 400);
      assert.match(body.error, /rule/i);
    });

    it('missing context field', async () => {
      const { status, body } = await post({ rule: 'ctx.x > 1' });
      assert.equal(status, 400);
      assert.match(body.error, /context/i);
    });

    it('context is null', async () => {
      const { status, body } = await post({ rule: 'ctx.x > 1', context: null });
      assert.equal(status, 400);
      assert.match(body.error, /context/i);
    });

    it('context is an array', async () => {
      const { status, body } = await post({ rule: 'ctx.x > 1', context: [1, 2] });
      assert.equal(status, 400);
      assert.match(body.error, /context/i);
    });

    it('context is a string', async () => {
      const { status, body } = await post({ rule: 'ctx.x > 1', context: 'bad' });
      assert.equal(status, 400);
      assert.match(body.error, /context/i);
    });

    it('syntax error in rule', async () => {
      const { status, body } = await post({
        rule: 'ctx.amount >>>',
        context: { amount: 5 },
      });
      assert.equal(status, 400);
      assert.match(body.error, /syntax/i);
    });

    it('incomplete expression', async () => {
      const { status, body } = await post({
        rule: 'ctx.amount >',
        context: { amount: 5 },
      });
      assert.equal(status, 400);
    });
  });

  // ── 400: disallowed AST node types (security) ─────────────────────────────

  describe('400 — disallowed expression constructs', () => {
    it('rejects function call expression', async () => {
      const { status, body } = await post({
        rule: 'process.exit(1)',
        context: {},
      });
      assert.equal(status, 400);
      assert.match(body.error, /disallowed/i);
    });

    it('rejects arrow function', async () => {
      const { status, body } = await post({
        rule: '(() => 42)()',
        context: {},
      });
      assert.equal(status, 400);
      assert.match(body.error, /disallowed/i);
    });

    it('rejects assignment expression', async () => {
      const { status, body } = await post({
        rule: 'ctx.x = 99',
        context: { x: 1 },
      });
      assert.equal(status, 400);
      assert.match(body.error, /disallowed/i);
    });

    it('rejects new expression', async () => {
      const { status, body } = await post({
        rule: 'new Date()',
        context: {},
      });
      assert.equal(status, 400);
      assert.match(body.error, /disallowed/i);
    });

    it('rejects computed member access (bracket notation)', async () => {
      const { status, body } = await post({
        rule: 'ctx["__proto__"]',
        context: {},
      });
      assert.equal(status, 400);
      assert.match(body.error, /computed member/i);
    });

    it('rejects sequence / comma expression', async () => {
      const { status, body } = await post({
        rule: '(1, process.exit(0))',
        context: {},
      });
      assert.equal(status, 400);
      assert.match(body.error, /disallowed/i);
    });

    it('rejects object expression literal', async () => {
      const { status, body } = await post({
        rule: '({ a: 1 }).a === 1',
        context: {},
      });
      assert.equal(status, 400);
      assert.match(body.error, /disallowed/i);
    });

    it('rejects array expression', async () => {
      const { status, body } = await post({
        rule: '[1,2,3].length > 0',
        context: {},
      });
      assert.equal(status, 400);
      assert.match(body.error, /disallowed/i);
    });
  });

  // ── 422: non-boolean result ────────────────────────────────────────────────

  describe('422 — non-boolean result', () => {
    it('returns 422 when rule evaluates to a number', async () => {
      const { status, body } = await post({
        rule: 'ctx.amount + 1',
        context: { amount: 5 },
      });
      assert.equal(status, 422);
      assert.match(body.error, /boolean/i);
    });

    it('returns 422 when rule evaluates to a string', async () => {
      const { status, body } = await post({
        rule: '"hello"',
        context: {},
      });
      assert.equal(status, 422);
      assert.match(body.error, /boolean/i);
    });

    it('returns 422 when rule evaluates to undefined (missing ctx property)', async () => {
      const { status, body } = await post({
        rule: 'ctx.nonexistent',
        context: {},
      });
      assert.equal(status, 422);
      assert.match(body.error, /boolean/i);
    });

    it('returns 422 when rule evaluates to null', async () => {
      const { status, body } = await post({
        rule: 'ctx.val',
        context: { val: null },
      });
      assert.equal(status, 422);
      assert.match(body.error, /boolean/i);
    });
  });
});

// ── Start ─────────────────────────────────────────────────────────────────────
// Only bind to a port when this file is run directly (`node app.js`).
// When require()'d by tests the caller controls the server lifecycle.

if (require.main === module) {
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`acme-rules listening on port ${PORT}`);
  });
}

module.exports = app; // export for testing

