 *
 * POST /check
 *   Body: { rule: string, context: object }
 *   Response 200: { result: boolean }
 *   Response 400: { error: string }   – missing/invalid fields or unsupported syntax
 *   Response 422: { error: string }   – rule evaluated but returned a non-boolean
 *   Response 500: { error: string }   – unexpected server error
 *
 * ─── SECURITY NOTE ────────────────────────────────────────────────────────────
 * docs/RULES_ENGINE.md proposes:
 *
 *   return Function('ctx', 'req', `return (${expr});`)(ctx.ctx, req);
 *
 * That pattern is Remote Code Execution (RCE). `new Function` / `eval` with
 * a caller-supplied string grants every client unrestricted access to the Node
 * process: file system, environment variables, network, child_process, etc.
 * Labelling it a "rules engine" does not make it safe. It is NOT implemented
 * here.
 *
 * This file uses a two-layer defence instead:
 *
 *   1. Static AST validation (validateExpr) — walks the parsed expression tree
 *      and rejects any node type that could cause side effects or escape the
 *      sandbox (CallExpression, AssignmentExpression, NewExpression, …).
 *      Only pure comparison / logical / arithmetic / member-access / literal
 *      nodes are allowed.
 *
 *   2. node:vm sandbox execution — even if a node type somehow slips through
 *      the allowlist, the script runs inside a vm.Script with a frozen,
 *      prototype-free context that has no reference to any built-in or global.
 *
 * The combination means an attacker cannot execute functions, mutate state, or
 * reach the host environment regardless of the expression they supply.
 * ──────────────────────────────────────────────────────────────────────────────
 */

'use strict';

const express = require('express');
const { parse } = require('acorn');        // lightweight, zero-dep JS parser
const vm = require('node:vm');

const app = express();
app.use(express.json());

// ── AST node types that are safe in a pure boolean expression ─────────────────
const ALLOWED_NODE_TYPES = new Set([
  'ExpressionStatement',
  'BinaryExpression',   // ==, ===, !=, !==, <, <=, >, >=, +, -, *, /, %
  'LogicalExpression',  // &&, ||, ??
  'UnaryExpression',    // !, -, + (unary), typeof
  'MemberExpression',   // ctx.amount, ctx.user.role
  'Identifier',         // ctx, individual property names
  'Literal',            // 42, "admin", true, null …
  'ConditionalExpression', // ternary a ? b : c
  'TemplateLiteral',    // `hello ${name}`
  'TemplateElement',
]);

/**
 * Recursively walk an Acorn AST node and throw if any node type is not on the
 * allowlist. This is a whitelist approach: unknown / new node types are denied
 * by default, which is the safe direction to fail.
 */
function validateExpr(node) {
  if (node === null || node === undefined) return;

  if (!ALLOWED_NODE_TYPES.has(node.type)) {
    throw new Error(`Disallowed expression type: ${node.type}`);
  }

  // Explicitly deny computed member access (ctx['__proto__']) even though
  // MemberExpression is otherwise allowed — static dot-access only.
  if (node.type === 'MemberExpression' && node.computed) {
    throw new Error('Computed member access (bracket notation) is not allowed');
  }

  // Deny dangerous unary operators that could leak type information or coerce
  // in surprising ways beyond the simple logical/arithmetic ones.
  if (node.type === 'UnaryExpression') {
    const allowed = new Set(['!', '-', '+', 'typeof', 'void']);
    if (!allowed.has(node.operator)) {
      throw new Error(`Disallowed unary operator: ${node.operator}`);
    }
  }

  // Walk all child nodes.
  for (const key of Object.keys(node)) {
    if (key === 'type' || key === 'start' || key === 'end' || key === 'loc') continue;
    const child = node[key];
    if (Array.isArray(child)) {
      child.forEach(validateExpr);
    } else if (child && typeof child === 'object' && typeof child.type === 'string') {
      validateExpr(child);
    }
  }
}

/**
 * Parse and statically validate a rule expression string.
 * Returns the Acorn AST Program node on success; throws a descriptive Error on
 * any syntax error or disallowed construct.
 *
 * We wrap the expression in `(${expr})` so that Acorn parses it as an
 * expression statement rather than requiring the caller to manage that detail.
 */
function parseAndValidate(expr) {
  let ast;
  try {
    ast = parse(`(${expr})`, { ecmaVersion: 2020 });
  } catch (err) {
    throw new Error(`Syntax error in rule expression: ${err.message}`);
  }

  // A valid expression program has exactly one ExpressionStatement body node.
  if (
    ast.type !== 'Program' ||
    ast.body.length !== 1 ||
    ast.body[0].type !== 'ExpressionStatement'
  ) {
    throw new Error('Rule must be a single expression');
  }

  validateExpr(ast.body[0]);
  return ast;
}

/**
 * Evaluate a pre-validated rule expression string against a plain-object
 * context using a locked-down vm sandbox.
 *
 * The sandbox contains only `ctx` (the caller-supplied context object). It has
 * no prototype, no reference to any global, built-in, or module. Even if the
 * static validator were somehow bypassed, the vm context provides a second,
 * independent containment layer.
 *
 * @param {string} expr     – rule expression, e.g. 'ctx.amount > 100'
 * @param {object} context  – the caller-supplied context object
 * @returns {*}             – the value the expression evaluated to
 */
function evalRule(expr, context) {
  // Build a prototype-free sandbox that only exposes `ctx`.
  const sandbox = Object.freeze(
    Object.assign(Object.create(null), { ctx: context })
  );
  vm.createContext(sandbox);

  const script = new vm.Script(`(${expr})`, {
    filename: 'rule',
    lineOffset: 0,
  });

  return script.runInContext(sandbox, { timeout: 50 }); // 50 ms hard timeout
}

// ── POST /check ───────────────────────────────────────────────────────────────

app.post('/check', (req, res) => {
  try {
    const { rule, context } = req.body ?? {};

    // ── Input validation ────────────────────────────────────────────────────
    if (typeof rule !== 'string' || rule.trim() === '') {
      return res.status(400).json({ error: '`rule` must be a non-empty string' });
    }
    if (context === undefined || context === null || typeof context !== 'object' || Array.isArray(context)) {
      return res.status(400).json({ error: '`context` must be a plain object' });
    }

    // ── Static AST validation ───────────────────────────────────────────────
    try {
      parseAndValidate(rule.trim());
    } catch (err) {
      return res.status(400).json({ error: err.message });
    }

    // ── Sandboxed evaluation ────────────────────────────────────────────────
    let result;
    try {
      result = evalRule(rule.trim(), context);
    } catch (err) {
      // vm timeout or runtime error inside the sandbox
      return res.status(400).json({ error: `Rule evaluation error: ${err.message}` });
    }

    // ── Type-check the result ───────────────────────────────────────────────
    if (typeof result !== 'boolean') {
      return res.status(422).json({
        error: `Rule must evaluate to a boolean, got ${typeof result}`,
      });
    }

    return res.status(200).json({ result });

  } catch (err) {
    // Catch-all for unexpected failures (e.g. malformed JSON body already
    // handled by express.json, but guard against anything else).
    console.error('Unexpected error in POST /check:', err);
    return res.status(500).json({ error: 'Internal server error' });
  }
});

// ── Start ─────────────────────────────────────────────────────────────────────

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`acme-rules listening on port ${PORT}`);
});

module.exports = app; // export for testing

