// Rule engine — safe, sandboxed evaluator (NO eval / new Function)
//
// Supports a simple expression grammar:
//   <field> <op> <literal>
//   <field>  : dot-path into the context object  (e.g. "amount", "user.role")
//   <op>     : one of  >  >=  <  <=  ==  !=
//   <literal>: a JSON number, a double-quoted string, true, false, or null
//
// Examples:
//   "amount > 100"
//   "user.role == \"admin\""
//   "score >= 0.5"
// ---------------------------------------------------------------------------

/**
 * Safely retrieve a nested value from `obj` using a dot-separated path.
 * Returns `undefined` if any segment is missing.
 * Rejects paths that try to escape to prototype properties.
 */
function getPath(obj, path) {
  const BLOCKED = new Set(['__proto__', 'prototype', 'constructor']);
  const segments = path.split('.');
  let cur = obj;
  for (const seg of segments) {
    if (BLOCKED.has(seg)) return undefined;
    if (cur === null || typeof cur !== 'object') return undefined;
    cur = Object.prototype.hasOwnProperty.call(cur, seg) ? cur[seg] : undefined;
  }
  return cur;
}

/** Parse a literal token into its JS value (number, string, boolean, null). */
function parseLiteral(token) {
  if (token === 'true')  return true;
  if (token === 'false') return false;
  if (token === 'null')  return null;

  // Double-quoted string — allow only printable ASCII to be safe
  if (/^"[^"]*"$/.test(token)) return token.slice(1, -1);

  // Finite number
  const n = Number(token);
  if (!Number.isNaN(n) && Number.isFinite(n)) return n;

  throw new Error(`Unsupported literal: ${token}`);
}

const ALLOWED_OPS = new Set(['>', '>=', '<', '<=', '==', '!=']);

/**
 * Evaluate a rule expression string against a context object.
 *
 * @param {string} expr    - Rule string, e.g. 'amount > 100'
 * @param {object} ctx     - Context object supplied by the caller
 * @returns {boolean}
 * @throws  {Error} on malformed expressions
 */
function evalRule(expr, ctx) {
  if (typeof expr !== 'string') throw new Error('rule must be a string');

  // Tokenise: field  op  literal
  // op is one of: >= <= != > < ==
  const RULE_RE = /^\s*([a-zA-Z_$][a-zA-Z0-9_.]*)\s*(>=|<=|!=|>|<|==)\s*(.+?)\s*$/;
  const match = RULE_RE.exec(expr);
  if (!match) throw new Error(`Invalid rule expression: "${expr}"`);

  const [, fieldPath, op, rawLiteral] = match;

  if (!ALLOWED_OPS.has(op)) throw new Error(`Unsupported operator: ${op}`);

  const fieldValue   = getPath(ctx, fieldPath);
  const literalValue = parseLiteral(rawLiteral);

  switch (op) {
    case '>':  return fieldValue >  literalValue;
    case '>=': return fieldValue >= literalValue;
    case '<':  return fieldValue <  literalValue;
    case '<=': return fieldValue <= literalValue;
    case '==': return fieldValue == literalValue; // eslint-disable-line eqeqeq
    case '!=': return fieldValue != literalValue; // eslint-disable-line eqeqeq
    default:   throw new Error(`Unhandled operator: ${op}`);
  }
