  }

  if (context === undefined || context === null || typeof context !== 'object' || Array.isArray(context)) {
    return res.status(400).json({ error: 'Missing or invalid "context" field (must be a plain object).' });
  }

  try {
    const result = evalRule(rule, context);
    return res.status(200).json({ result: Boolean(result) });
  } catch (err) {
    return res.status(400).json({ error: err.message });
  }
});

