{
  "name": "acme-rules-engine",
  "version": "1.0.0",
  "description": "Dynamic Rule Engine for ACME",
  "main": "app.js",
  "scripts": {
    "start": "node app.js",
    "test": "node test_check_endpoint.js"
  },
  "dependencies": {
    "express": "^4.18.2"
  }
}

// Test script for POST /check endpoint
const http = require('http');

// Test cases
const testCases = [
  {
    name: 'Test 1: amount > 100 && user === "admin" (true)',
    data: {
      rule: 'ctx.amount > 100 && ctx.user === "admin"',
      context: {
        amount: 150,
        user: 'admin'
      }
    },
    expected: true
  },
  {
    name: 'Test 2: amount > 100 && user === "admin" (false - amount too low)',
    data: {
      rule: 'ctx.amount > 100 && ctx.user === "admin"',
      context: {
        amount: 50,
        user: 'admin'
      }
    },
    expected: false
  },
  {
    name: 'Test 3: amount > 100 && user === "admin" (false - wrong user)',
    data: {
      rule: 'ctx.amount > 100 && ctx.user === "admin"',
      context: {
        amount: 150,
        user: 'user'
      }
    },
    expected: false
  },
  {
    name: 'Test 4: Simple comparison (true)',
    data: {
      rule: 'ctx.value === "test"',
      context: {
        value: 'test'
      }
    },
    expected: true
  },
  {
    name: 'Test 5: Access to req object',
    data: {
      rule: 'req.method === "POST"',
      context: {}
    },
    expected: true
  }
];

function runTest(testCase) {
  return new Promise((resolve, reject) => {
    const postData = JSON.stringify(testCase.data);

    const options = {
      hostname: 'localhost',
      port: 3000,
      path: '/check',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData)
      }
    };

    const req = http.request(options, (res) => {
      let responseData = '';

      res.on('data', (chunk) => {
        responseData += chunk;
      });

      res.on('end', () => {
        try {
          const result = JSON.parse(responseData);
          const passed = result.result === testCase.expected;

          resolve({
            name: testCase.name,
            passed,
            response: result,
            expected: testCase.expected
          });
        } catch (e) {
          reject(new Error(`Failed to parse response: ${e.message}`));
        }
      });
    });

    req.on('error', (e) => {
      reject(new Error(`Request failed: ${e.message}`));
    });

    req.write(postData);
    req.end();
  });
}

async function runAllTests() {
  console.log('Starting tests for POST /check endpoint...\n');

  for (const testCase of testCases) {
    try {
      const result = await runTest(testCase);

      if (result.passed) {
        console.log(`✓ ${result.name}`);
      } else {
        console.log(`✗ ${result.name}`);
        console.log(`  Expected: ${result.expected}`);
        console.log(`  Got: ${result.response.result}`);
      }
    } catch (error) {
      console.log(`✗ ${testCase.name} - Error: ${error.message}`);
    }

    // Small delay between tests
    await new Promise(resolve => setTimeout(resolve, 100));
  }

  console.log('\nTests completed!');
}

// Run tests if server is running
runAllTests().catch(console.error);

