// Minimal HTTP server implementation without express
const http = require('http');

// Evaluate a caller-supplied rule expression against the request.
function evalRule(body) {
  const expr = body.rule; // e.g. 'ctx.amount > 100'
  const ctx = body.context;
  const req = {}; // Simplified req object for this implementation
  return Function('ctx', 'req', `return (${expr});`)(ctx, req); // dynamic eval
}

function parseRequestBody(req) {
  return new Promise((resolve, reject) => {
    let body = '';
    req.on('data', chunk => {
      body += chunk.toString();
    });
    req.on('end', () => {
      try {
        resolve(JSON.parse(body));
      } catch (e) {
        reject(e);
      }
    });
    req.on('error', reject);
  });
}

const server = http.createServer(async (req, res) => {
  // Set CORS headers
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

  // Handle OPTIONS preflight
  if (req.method === 'OPTIONS') {
    res.writeHead(200);
    res.end();
    return;
  }

  // Set JSON content type
  res.setHeader('Content-Type', 'application/json');

  // Route handling
  if (req.method === 'GET' && req.url === '/health') {
    res.writeHead(200);
    res.end(JSON.stringify({ status: 'ok', timestamp: new Date().toISOString() }));
    return;
  }

  if (req.method === 'GET' && req.url === '/users') {
    res.writeHead(200);
    res.end(JSON.stringify([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]));
    return;
  }

  if (req.method === 'POST' && req.url === '/check') {
    try {
      const body = await parseRequestBody(req);

      // Check if rule and context are provided
      if (!body.rule || !body.context) {
        res.writeHead(400);
        res.end(JSON.stringify({
          error: 'Missing required fields: rule and context must be provided'
        }));
        return;
      }

      // Evaluate the rule
      const result = evalRule(body);

      // Return the evaluation result
      res.writeHead(200);
      res.end(JSON.stringify({
        rule: body.rule,
        context: body.context,
        result: result
      }));
    } catch (error) {
      // Handle any errors during evaluation
