        rule: 123, context: { amount: 50 },
      });
      assert.strictEqual(status, 400);
      assert.ok(body.error);
    });

    await test('400: missing context field', async () => {
      const { status, body } = await post(server, '/check', {
        rule: 'ctx.x > 1',
      });
      assert.strictEqual(status, 400);
      assert.ok(body.error);
    });

    await test('400: context is an array', async () => {
      const { status, body } = await post(server, '/check', {
        rule: 'ctx.x > 1', context: [1, 2, 3],
      });
      assert.strictEqual(status, 400);
      assert.ok(body.error);
    });

    await test('400: syntax error in rule', async () => {
      const { status, body } = await post(server, '/check', {
        rule: 'ctx.x >>>', context: { x: 1 },
      });
      assert.strictEqual(status, 400);
      assert.ok(body.error);
    });

    // 400 — security payloads rejected at HTTP level
    await test('400: RCE attempt via process.env', async () => {
      const { status, body } = await post(server, '/check', {
        rule: 'process.env.SECRET', context: {},
      });
      assert.strictEqual(status, 400);
      assert.ok(body.error);
    });

    await test('400: RCE attempt via require', async () => {
      const { status, body } = await post(server, '/check', {
        rule: "require('child_process').execSync('id')", context: {},
      });
      assert.strictEqual(status, 400);
      assert.ok(body.error);
    });

    await test('400: prototype pollution attempt', async () => {
      const { status, body } = await post(server, '/check', {
        rule: 'ctx.__proto__', context: {},
      });
      assert.strictEqual(status, 400);
      assert.ok(body.error);
    });

  } finally {
    await new Promise((resolve) => server.close(resolve));
  }
}

// ─── Run everything ───────────────────────────────────────────────────────────

(async () => {
  try {
    await unitTests();
    await securityTests();
    await integrationTests();
  } catch (err) {
    console.error('\nUnexpected test-runner error:', err);
    process.exitCode = 1;
    return;
  }

  console.log(`\n${'─'.repeat(58)}`);
  console.log(`  ${passed + failed} tests: ${passed} passed, ${failed} failed`);
  if (failed > 0) {
    console.error(`  ${failed} test(s) FAILED`);
    process.exitCode = 1;
  } else {
    console.log('  All tests passed ✓');
  }
})();

/**
 * Evaluate an AST node against `scope`, an internal lookup object of the form:
 *   { ctx: <caller-supplied context object> }
 *
 * Rules are authored as `ctx.amount > 100`, so `ctx` is the one top-level
 * identifier the engine exposes; it resolves to the caller-supplied context.
 * No other identifiers are resolvable, keeping the scope hermetically sealed.
 *
 * Only pure data access and safe operators are permitted; no function calls
 * or assignments are possible because those node types are never produced by
 * the parser above.
 *
 * @param {object} node   AST node
 * @param {object} scope  Internal scope: { ctx: <context object> }
 * @returns {unknown}
 */
function interpret(node, scope) {
  switch (node.type) {

    case 'Literal':
      return node.value;

    case 'Identifier':
      // Only 'ctx' is resolvable; everything else is undefined.
      // 'ctx' is already guaranteed not to be a banned identifier by the
      // tokeniser, and it maps to the caller-supplied context object.
      if (!Object.prototype.hasOwnProperty.call(scope, node.name)) {
        return undefined;
      }
      return scope[node.name];

