// app.js — acme-rules dynamic rule engine
'use strict';

const express = require('express');
const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Safe rule evaluator
//
// WHY NOT the reference implementation?
// docs/RULES_ENGINE.md suggests:
//
//   Function('ctx', 'req', `return (${expr});`)(ctx.ctx, req)
//
// That passes a raw, caller-controlled string to the Function constructor,
// which is identical in power to eval().  Any client can execute arbitrary
// code in the server process (RCE), crash the server with an infinite loop,
// or exfiltrate secrets.  The reference implementation MUST NOT be used.
//
// WHAT WE DO INSTEAD:
// We parse the rule string into a small AST using a recursive-descent parser
// that understands only the operators the engine actually needs, then
// walk that AST to produce a boolean result.  No dynamic code execution
// takes place at any point.
// ---------------------------------------------------------------------------

// ── Tokeniser ───────────────────────────────────────────────────────────────

const TT = {
  NUMBER: 'NUMBER',
  STRING: 'STRING',
  BOOL:   'BOOL',
  NULL:   'NULL',
  IDENT:  'IDENT',   // ctx.foo.bar
  OP:     'OP',
  LPAREN: 'LPAREN',
  RPAREN: 'RPAREN',
  EOF:    'EOF',
};

/**
 * Lex `src` into an array of tokens.
 * Supported operators: > >= < <= === !== == != && || !
 * Supported literals:  numbers, single- or double-quoted strings, true, false, null
 * Supported identifiers: dot-separated names, e.g. ctx.user.age
 */
function tokenise(src) {
  const tokens = [];
  let i = 0;

  while (i < src.length) {
    // Skip whitespace
    if (/\s/.test(src[i])) { i++; continue; }

    // Numbers (integer or decimal, optional leading minus handled as unary)
    if (/[0-9]/.test(src[i]) || (src[i] === '.' && /[0-9]/.test(src[i + 1]))) {
      let raw = '';
      while (i < src.length && /[0-9.]/.test(src[i])) raw += src[i++];
      const value = Number(raw);
      if (Number.isNaN(value)) throw new SyntaxError(`Invalid number: ${raw}`);
      tokens.push({ type: TT.NUMBER, value });
      continue;
    }

    // Strings
    if (src[i] === '"' || src[i] === "'") {
      const quote = src[i++];
      let str = '';
      while (i < src.length && src[i] !== quote) {
        if (src[i] === '\\') {
          i++;
          const esc = { n: '\n', t: '\t', r: '\r', '\\': '\\', "'": "'", '"': '"' }[src[i]];
          if (esc === undefined) throw new SyntaxError(`Unknown escape: \\${src[i]}`);
          str += esc;
        } else {
          str += src[i];
        }
        i++;
      }
      if (i >= src.length) throw new SyntaxError('Unterminated string literal');
      i++; // closing quote
      tokens.push({ type: TT.STRING, value: str });
      continue;
    }

    // Multi-character operators (longest-match first)
    const multiOp = ['===', '!==', '>=', '<=', '&&', '||'];
    const matchedMulti = multiOp.find(op => src.startsWith(op, i));
    if (matchedMulti) {
      tokens.push({ type: TT.OP, value: matchedMulti });
      i += matchedMulti.length;
      continue;
    }

    // Single-character operators / punctuation
    if ('><=!'.includes(src[i])) {
      // These are single-char versions (> < = ! not followed by = or another =)
      tokens.push({ type: TT.OP, value: src[i] });
      i++;
      continue;
    }
    if (src[i] === '(') { tokens.push({ type: TT.LPAREN }); i++; continue; }
    if (src[i] === ')') { tokens.push({ type: TT.RPAREN }); i++; continue; }

    // Keywords and dot-path identifiers: ctx.foo.bar
    if (/[A-Za-z_$]/.test(src[i])) {
      let name = '';
      while (i < src.length && /[A-Za-z0-9_$.]/.test(src[i])) name += src[i++];
      // Remove any trailing dot
      if (name.endsWith('.')) throw new SyntaxError(`Trailing dot in identifier: ${name}`);
      if (name === 'true')  { tokens.push({ type: TT.BOOL, value: true });  continue; }
      if (name === 'false') { tokens.push({ type: TT.BOOL, value: false }); continue; }
      if (name === 'null')  { tokens.push({ type: TT.NULL, value: null });  continue; }
      tokens.push({ type: TT.IDENT, value: name });
      continue;
    }

    throw new SyntaxError(`Unexpected character: '${src[i]}' at position ${i}`);
  }

  tokens.push({ type: TT.EOF });
  return tokens;
}

// ── Parser (recursive descent) ───────────────────────────────────────────────
//
// Grammar (lowest → highest precedence):
//
//   expr      → or
//   or        → and  ( '||' and  )*
//   and       → cmp  ( '&&' cmp  )*
//   cmp       → add  ( ('==='|'!=='|'=='|'!='|'>'|'>='|'<'|'<=') add )*
//   add       → unary
//   unary     → '!' unary | primary
//   primary   → NUMBER | STRING | BOOL | NULL | IDENT | '(' expr ')'

function parse(tokens) {
  let pos = 0;

  function peek()    { return tokens[pos]; }
  function consume() { return tokens[pos++]; }

  function expect(type, value) {
    const tok = consume();
    if (tok.type !== type || (value !== undefined && tok.value !== value)) {
      throw new SyntaxError(
        `Expected ${type}${value !== undefined ? ` '${value}'` : ''}, got ${tok.type} '${tok.value}'`
      );
    }
    return tok;
  }

  function parseExpr()    { return parseOr(); }

  function parseOr() {
    let left = parseAnd();
    while (peek().type === TT.OP && peek().value === '||') {
      consume();
      const right = parseAnd();
      left = { type: 'BinaryOp', op: '||', left, right };
    }
    return left;
  }

  function parseAnd() {
    let left = parseCmp();
    while (peek().type === TT.OP && peek().value === '&&') {
      consume();
      const right = parseCmp();
      left = { type: 'BinaryOp', op: '&&', left, right };
    }
    return left;
  }

  const CMP_OPS = new Set(['===', '!==', '==', '!=', '>', '>=', '<', '<=']);

  function parseCmp() {
    let left = parseUnary();
    while (peek().type === TT.OP && CMP_OPS.has(peek().value)) {
      const op = consume().value;
      const right = parseUnary();
      left = { type: 'BinaryOp', op, left, right };
    }
    return left;
  }

  function parseUnary() {
    if (peek().type === TT.OP && peek().value === '!') {
      consume();
      return { type: 'UnaryOp', op: '!', operand: parseUnary() };
    }
    // Unary minus for numeric literals, e.g. -1
    if (peek().type === TT.OP && peek().value === '-') {
      consume();
      const operand = parsePrimary();
      if (operand.type !== 'Literal' || typeof operand.value !== 'number') {
        throw new SyntaxError('Unary minus is only supported on numeric literals');
      }
      return { type: 'Literal', value: -operand.value };
    }
    return parsePrimary();
  }

  function parsePrimary() {
    const tok = peek();

    if (tok.type === TT.NUMBER || tok.type === TT.STRING ||
        tok.type === TT.BOOL   || tok.type === TT.NULL) {
      consume();
      return { type: 'Literal', value: tok.value };
    }

    if (tok.type === TT.IDENT) {
      consume();
      return { type: 'Identifier', path: tok.value };
    }

    if (tok.type === TT.LPAREN) {
      consume();
      const inner = parseExpr();
      expect(TT.RPAREN);
      return inner;
    }

    throw new SyntaxError(`Unexpected token: ${tok.type} '${tok.value}' at position ${pos}`);
  }

  const tree = parseExpr();

  if (peek().type !== TT.EOF) {
    throw new SyntaxError(`Unexpected token after expression: '${peek().value}'`);
  }

  return tree;
}

// ── AST evaluator ────────────────────────────────────────────────────────────

/**
 * Resolve a dot-path identifier against the supplied context object.
 * e.g. 'ctx.user.age' → ctx['user']['age']
 *
 * The first segment MUST be 'ctx'; anything else is rejected so that callers
 * cannot reference server-side variables such as `process` or `require`.
 */
function resolvePath(path, ctx) {
  const parts = path.split('.');

  if (parts[0] !== 'ctx') {
    throw new EvalError(
      `Identifier '${path}' is not allowed. Rule identifiers must start with 'ctx'.`
    );
  }

  // Walk into the context object
  let value = ctx;
  for (const part of parts.slice(1)) {
    if (value === null || value === undefined) return undefined;
    if (typeof value !== 'object' || Array.isArray(value)) {
      throw new EvalError(`Cannot access property '${part}' on a non-object value`);
    }
    value = Object.prototype.hasOwnProperty.call(value, part) ? value[part] : undefined;
  }
  return value;
}

function evalNode(node, ctx) {
  switch (node.type) {

    case 'Literal':
      return node.value;

    case 'Identifier':
      return resolvePath(node.path, ctx);

    case 'UnaryOp':
      if (node.op === '!') return !evalNode(node.operand, ctx);
      throw new EvalError(`Unknown unary operator: ${node.op}`);

    case 'BinaryOp': {
      // Short-circuit logical operators
      if (node.op === '&&') return evalNode(node.left, ctx) && evalNode(node.right, ctx);
      if (node.op === '||') return evalNode(node.left, ctx) || evalNode(node.right, ctx);

      const l = evalNode(node.left,  ctx);
      const r = evalNode(node.right, ctx);

      switch (node.op) {
        case '===': return l === r;
        case '!==': return l !== r;
        case '==':  return l == r;   // eslint-disable-line eqeqeq
        case '!=':  return l != r;   // eslint-disable-line eqeqeq
        case '>':   return l >   r;
        case '>=':  return l >=  r;
        case '<':   return l <   r;
        case '<=':  return l <=  r;
        default:    throw new EvalError(`Unknown binary operator: ${node.op}`);
      }
    }

    default:
      throw new EvalError(`Unknown AST node type: ${node.type}`);
  }
}

/**
 * Public entry point.
 * Parses and evaluates `expr` against `ctx`, returning a boolean.
 * Throws SyntaxError (bad rule) or EvalError (bad context access).
 */
function evalRule(expr, ctx) {
  if (typeof expr !== 'string' || expr.trim() === '') {
    throw new SyntaxError('rule must be a non-empty string');
  }
  const tokens = tokenise(expr);
  const ast    = parse(tokens);
  const result = evalNode(ast, ctx);
  return Boolean(result);
}

// ── POST /check ──────────────────────────────────────────────────────────────

/**
 * POST /check
 *
 * Request body (JSON):
 *   {
 *     "rule":    "<expression>",   // required — e.g. "ctx.amount > 100"
 *     "context": { ... }           // required — data the rule is evaluated against
 *   }
 *
 * Successful response 200:
 *   { "result": true | false }
 *
 * Error response 400:
 *   { "error": "<message>" }
 */
app.post('/check', (req, res) => {
  const { rule, context } = req.body ?? {};

  if (rule === undefined || rule === null) {
    return res.status(400).json({ error: 'Missing required field: rule' });
  }
  if (context === undefined || context === null) {
    return res.status(400).json({ error: 'Missing required field: context' });
  }
  if (typeof context !== 'object' || Array.isArray(context)) {
    return res.status(400).json({ error: 'context must be a JSON object' });
  }

  try {
    const result = evalRule(rule, context);
    return res.status(200).json({ result });
  } catch (err) {
    // SyntaxError  → bad rule expression
    // EvalError    → invalid identifier / bad property access
    const status = (err instanceof SyntaxError || err instanceof EvalError) ? 400 : 500;
    return res.status(status).json({ error: err.message });
  }
});

// ── Server ───────────────────────────────────────────────────────────────────

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`acme-rules listening on port ${PORT}`));

module.exports = { app, evalRule }; // export for testing

